//! Mellow desktop client: a Discord-like shell (ADR-0012) on the shared client core (ADR-0011).

mod clipboard;
mod demo_shell;
mod fake_messages;
mod fake_workspace;
mod live_rows;
mod live_shell;
mod message_markup;
mod scroll_benchmark;
mod shell_rows;
mod window_snapshot;

use slint::ComponentHandle as _;

use crate::generated_ui::AppWindow;

mod generated_ui {
    // Generated by slint-build: our workspace lints do not apply to code we do not write.
    #![allow(
        missing_debug_implementations,
        clippy::all,
        clippy::pedantic,
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::panic,
        clippy::todo
    )]
    slint::include_modules!();
}

/// Starts the shell on fake data instead of signing in to an instance.
const DEMO_WORKSPACE_VARIABLE: &str = "MELLOW_DEMO_WORKSPACE";
/// Network calls never need more: the UI thread does the rest.
const NETWORK_WORKER_THREADS: usize = 2;

/// The list only knows its full height after a layout pass, so scroll on the next tick.
pub fn scroll_to_latest_message_after_layout(window: &AppWindow) {
    let weak_window = window.as_weak();
    slint::Timer::single_shot(std::time::Duration::ZERO, move || {
        if let Some(window) = weak_window.upgrade() {
            window.invoke_scroll_to_latest_message();
        }
    });
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_writer(std::io::stderr)
        .init();
    let window = AppWindow::new()?;

    // The scroll benchmark and snapshots measure the shell itself, on stable fake data.
    let is_demo = [
        DEMO_WORKSPACE_VARIABLE,
        scroll_benchmark::ENABLE_SCROLL_BENCHMARK_VARIABLE,
        window_snapshot::SNAPSHOT_DIRECTORY_VARIABLE,
    ]
    .iter()
    .any(|variable| std::env::var_os(variable).is_some());

    if is_demo {
        demo_shell::start(&window)?;
        if let Some(directory) = std::env::var_os(window_snapshot::SNAPSHOT_DIRECTORY_VARIABLE) {
            window_snapshot::schedule(&window, directory.into());
        }
        window.run()?;
        return Ok(());
    }

    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(NETWORK_WORKER_THREADS)
        .enable_all()
        .build()?;
    let shell = live_shell::start(&window, runtime.handle().clone());
    window.run()?;
    live_shell::sign_out_before_exit(&shell);
    Ok(())
}
